'use client';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const RegisterSchema = z.object({
  email: z.string().email('Email không hợp lệ'),
  password: z.string().min(8, 'Mật khẩu phải từ 8 ký tự'),
  confirmPassword: z.string(),
}).refine((data) => data.password === data.confirmPassword, {
  message: 'Mật khẩu nhập lại không khớp',
  path: ['confirmPassword'],
});

type RegisterFormData = z.infer<typeof RegisterSchema>;

export function RegisterForm() {
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<RegisterFormData>({
    resolver: zodResolver(RegisterSchema),
  });

  const onSubmit = async (data: RegisterFormData) => {
    await apiRegister(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
      <div>
        <input {...register('email')} placeholder="Email" />
        {errors.email && <p className="text-red-500">{errors.email.message}</p>}
      </div>
      <button disabled={isSubmitting}>{isSubmitting ? 'Loading...' : 'Register'}</button>
    </form>
  );
}

'use server';
import { z } from 'zod';
import { db } from '@/lib/db';

const ProfileSchema = z.object({
  bio: z.string().max(200, 'Bio tối đa 200 ký tự'),
});

export async function updateBioAction(prevState: any, formData: FormData) {
  const validated = ProfileSchema.safeParse({
    bio: formData.get('bio'),
  });

  if (!validated.success) {
    return { success: false, errors: validated.error.flatten().fieldErrors };
  }

  await db.user.update({ data: validated.data });
  return { success: true, errors: null };
}
